import { Link, useNavigate } from "react-router-dom";
import LogoutButton from "./LogoutButton";
import { getUserRole, isLoggedIn } from "../auth";

export default function Navbar() {
  const role = getUserRole();
  const navigate = useNavigate();

  return (
    <nav className="bg-gray-900 text-white px-6 py-4 flex justify-between items-center shadow-md">
      <Link to="/" className="text-2xl font-bold text-green-400">TutorMatch</Link>
      <div className="flex gap-6 items-center">
        {!isLoggedIn() && (
          <>
            <Link to="/student/register" className="hover:underline">Register as Student</Link>
            <Link to="/tutor/register" className="hover:underline">Register as Tutor</Link>
            <Link to="/login" className="hover:underline">Login</Link>
          </>
        )}

        {isLoggedIn() && (
          <>
            {role === "student" && (
              <Link to="/student/dashboard" className="hover:underline">Dashboard</Link>
            )}
            {role === "tutor" && (
              <Link to="/tutor/dashboard" className="hover:underline">Dashboard</Link>
            )}
            <Link to="/match" className="hover:underline">Match</Link>
            <LogoutButton />
          </>
        )}
      </div>
    </nav>
  );
}
